package main

import (
    "errors"
    "math"
)

var ErrOverflow = errors.New("integer overflow")

func SafeAddInt32(a, b int32) (int32, error) {
    if (b > 0 && a > math.MaxInt32-b) || (b < 0 && a < math.MinInt32-b) {
        return 0, ErrOverflow
    }
    return a + b, nil
}

注记：
1. 正溢出判定：b > 0 时，若 a > MaxInt32 - b 则相加必定上溢。
2. 负溢出判定：b < 0 时，若 a < MinInt32 - b 则相加必定下溢。
3. 相加前利用逆运算做边界校验，避免直接计算触发未定义行为或回绕。

PostgreSQL 14 的逻辑复制槽不用 extension，直接在主库上查就行，主要看槽位是否 active、有没有卡住不消费、restart_lsn 和 confirmed_flush_lsn 差多少（积压的量）。常用一条：
SELECT slot_name, plugin, slot_type, active, restart_lsn, confirmed_flush_lsn, pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS retained_wal FROM pg_replication_slots WHERE slot_type='logical';
再补一条看订阅端消费延迟：SELECT subname, pid, received_lsn, latest_end_lsn, latest_end_time FROM pg_stat_subscription;
重点盯 active=false 但 restart_lsn 还在往前走之前就一直不动的槽，那种会把主库 WAL 撑满。要不要我再给你一个自动告警阈值的版本？

```go
// addInt32Safe 返回 int32 安全加法结果与是否溢出
func addInt32Safe(a, b int32) (int32, bool) {
	if b > 0 && a > math.MaxInt32-b {
		return 0, false
	}
	if b < 0 && a < math.MinInt32-b {
		return 0, false
	}
	return a + b, true
}
```
注记：用 MaxInt32-b 做上界比较，避免 a+b 先溢出；返回 ok=false 表示越界，调用方决定报错还是降级。

